<script setup lang="ts">
import{ref,computed,onMounted}from'vue';import{Search,Download,History,BarChart3,Users,CalendarDays}from'@lucide/vue';
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']);const options=ref<any[]>([]),dimension=ref('daily'),clinicIds=ref<string[]>([]),fromDay=ref(''),toDay=ref(''),employeeId=ref(''),itemKey=ref(''),current=ref<any>(null),history=ref<any[]>([]),next=ref<string|null>(null),canExport=ref(false),busy=ref(false),loading=ref(false),error=ref(''),notice=ref('');
const names:Record<string,string>={daily:'经营日报',staff:'医护工作量',income:'收入构成'},status:Record<string,string>={known_sources:'已登记来源可核对',no_records:'所选期间无已登记来源',needs_verification:'有待核实项'},clinics=computed(()=>options.value.find(x=>x.dimension===dimension.value)?.clinics||[]),report=computed(()=>current.value?.snapshot.report),short=(s:string)=>s.slice(0,8).toUpperCase(),time=(s:string)=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
async function request(path:string,body?:any){const a=new AbortController(),timer=setTimeout(()=>a.abort(),20000);try{const r=await fetch('/api/v1/business'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:a.signal}),b=await r.json();if(!r.ok){if(r.status===401)emit('unauthorized');throw Error(b.message||'经营查询失败。');}return b;}finally{clearTimeout(timer);}}
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';
async function initialize(){loading.value=true;try{const b=await request('/bootstrap');options.value=b.options;dimension.value=b.options[0].dimension;clinicIds.value=b.options[0].clinics.map((c:any)=>c.id);fromDay.value=toDay.value=b.today;canExport.value=b.canExport;await loadHistory();}catch(e){error.value=explain(e);}finally{loading.value=false;}}
function changeDimension(){clinicIds.value=clinics.value.map((c:any)=>c.id);employeeId.value='';itemKey.value='';}
async function query(){busy.value=true;error.value='';notice.value='';try{current.value=await request('/reports',{dimension:dimension.value,clinicIds:clinicIds.value,fromDay:fromDay.value,toDay:toDay.value,employeeId:employeeId.value||null,itemKey:itemKey.value||null});await loadHistory();}catch(e){error.value=explain(e);current.value=null;}finally{busy.value=false;}}
async function loadHistory(more=false){const r=await request('/history'+(more&&next.value?'?beforeId='+next.value:''));history.value=more?[...history.value,...r.items]:r.items;next.value=r.next;}
async function read(id:string){busy.value=true;error.value='';notice.value='';try{current.value=await request('/reports/'+id);const f=current.value.snapshot.filters;dimension.value=f.dimension;clinicIds.value=[...f.clinicIds];fromDay.value=f.fromDay;toDay.value=f.toDay;employeeId.value=f.employeeId||'';itemKey.value=f.itemKey||'';}catch(e){error.value=explain(e);current.value=null;}finally{busy.value=false;}}
async function download(){if(!current.value)return;busy.value=true;error.value='';try{const r=await request('/reports/'+current.value.id+'/export',{viewToken:current.value.viewToken}),bytes=new TextEncoder().encode(r.csv),digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(bytes.byteLength!==r.bytes||digest!==r.sha256)throw Error('文件摘要或字节数不符，未下载。');const url=URL.createObjectURL(new Blob([bytes],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=r.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='已校验文件并触发浏览器下载，请在下载列表核对。';}catch(e){error.value=explain(e);}finally{busy.value=false;}}
function width(amount:string){const cents=(s:string)=>BigInt(s.replace('.','')),n=cents(report.value?.filteredReceivedAmount||'0.00');return n?Number(cents(amount)*10000n/n)/100:0;}
defineExpose({refresh:initialize});onMounted(initialize);
</script>
<template><div class="business-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><section class="b-card biz-filter"><div class="biz-heading"><div><div class="b-eyebrow">CLINIC BUSINESS</div><h2>从实际业务，看清日常经营</h2><p>接诊、开单和实收分别核对，每次查询保留自己的数据时点。</p></div><BarChart3 :size="30" :stroke-width="1.5"/></div><div class="biz-fields"><label>查询维度<select v-model="dimension" :disabled="busy||loading" @change="changeDimension"><option v-for="o in options" :key="o.dimension" :value="o.dimension">{{names[o.dimension]}}</option></select></label><label>开始业务日<input v-model="fromDay" type="date" :disabled="busy||loading"/></label><label>结束业务日<input v-model="toDay" type="date" :disabled="busy||loading"/></label></div><fieldset><legend>查询诊所</legend><label v-for="c in clinics" :key="c.id" class="b-checkbox"><input type="checkbox" v-model="clinicIds" :value="c.id" :disabled="busy||loading"/><span>{{c.name}}</span></label></fieldset><label v-if="dimension==='staff'&&report?.dimension==='staff'">可选人员<select v-model="employeeId" :disabled="busy||loading"><option value="">本次来源中的全部人员</option><option v-for="p in report.options.employees" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label v-if="dimension==='income'&&report?.dimension==='income'">可选项目 / 商品<select v-model="itemKey" :disabled="busy||loading"><option value="">全部已核对实收项目和商品</option><option v-for="p in report.options.items" :key="p.key" :value="p.key">{{p.name}}</option></select></label><div class="biz-actions"><button class="b-button" :disabled="busy||loading||!clinicIds.length" @click="query"><Search :size="17"/>{{busy?'正在核对…':'查询并保存原版'}}</button><span>先查询，再按来源中的人员或项目细看；修改条件后重新查询。单次1—93日。</span></div></section>
<section v-if="current" class="biz-results"><div class="biz-result-head"><div><h2>{{names[report.dimension]}}</h2><p>{{current.snapshot.filters.fromDay}} 至 {{current.snapshot.filters.toDay}} · {{current.snapshot.clinics.map((c:any)=>c.name).join('、')}}</p><small>原查询 {{short(current.id)}} · 数据时点 {{time(current.snapshot.dataAsOf)}} · {{status[report.status]}}</small></div><button v-if="canExport" class="b-button outline" :disabled="busy||loading" @click="download"><Download :size="17"/>导出此查询CSV</button></div><div class="biz-metrics"><article class="b-card"><small>实际到院 / 去重患者</small><strong>{{report.totals.arrivals}} <span>/ {{report.totals.patients}}</span></strong><p>同一患者多次到院，分别记次数</p></article><article class="b-card"><small>已知开单额</small><strong>¥ {{report.totals.knownOpenedAmount}}</strong><p>治疗{{report.totals.treatmentBills}}单、商品{{report.totals.sales}}单 · 待核实{{report.totals.unknownOpened}}单</p></article><article class="b-card"><small>实际到账</small><strong>¥ {{report.totals.receivedAmount}}</strong><p>治疗{{report.totals.treatmentReceivedAmount}} · 商品{{report.totals.productReceivedAmount}}</p></article><article class="b-card"><small>本期开单中已知待付款</small><strong>¥ {{report.totals.knownUnpaidOpenedAmount}}</strong><p>截至本次查询，待付款不计收入</p></article></div><p v-if="report.status==='no_records'" class="b-alert warning">没有查到所选期间已登记来源；仍须核实是否漏登，不代表诊所完全无业务。</p>
<section v-if="report.dimension==='daily'" class="b-card biz-block"><h3><CalendarDays :size="20"/>经营日报</h3><div class="biz-table"><table><thead><tr><th>日期 / 诊所</th><th>到院 / 患者</th><th>已开始 / 已结束</th><th>已知开单额</th><th>实际到账</th></tr></thead><tbody><tr v-for="d in report.daily" :key="d.date+d.clinicId"><td>{{d.date}}<small>{{d.clinicName}}</small></td><td>{{d.arrivals}} / {{d.patients}}</td><td>{{d.started}} / {{d.ended}}</td><td>¥ {{d.knownOpenedAmount}}<small>待核实{{d.unknownOpened}}单</small></td><td>¥ {{d.receivedAmount}}</td></tr></tbody></table></div><p class="b-help">接诊进展属于该日到院记录；各日、各店患者人数不能简单相加为全范围人数。</p></section>
<section v-if="report.dimension==='staff'" class="b-card biz-block"><h3><Users :size="20"/>医护工作量与治疗实收关联</h3><p class="b-alert warning">同一笔治疗实收可关联医生和多名护士，下面的关联金额不能跨人相加，也不是工资或已分配季度业绩。商品实收不自动归给医护。</p><div class="biz-table"><table><thead><tr><th>人员 / 诊所</th><th>医生已开始接诊</th><th>护士登记参与</th><th>关联治疗实收</th><th>关联笔数</th></tr></thead><tbody><tr v-for="p in report.staff" :key="p.clinicId+p.employeeId"><td>{{p.employeeName}}<small>{{p.clinicName}}</small></td><td>{{p.doctorStarted}}</td><td>{{p.nurseParticipation}}</td><td>¥ {{p.linkedTreatmentReceivedAmount}}</td><td>{{p.linkedReceiptCount}}<small v-if="p.unknownRoleReceipts">岗位待核实{{p.unknownRoleReceipts}}</small></td></tr></tbody></table></div><p>参与关联待核实治疗实收：¥ {{report.unlinkedTreatmentAmount}}。到院工作量与到账关联采用各自实际期间。</p></section>
<section v-if="report.dimension==='income'" class="b-card biz-block"><h3>收入构成</h3><p>本次项目筛选实收：<strong>¥ {{report.filteredReceivedAmount}}</strong> · 全范围未分清项目金额：¥ {{report.unclassifiedAmount}}</p><div class="biz-composition"><div><h4>项目与商品</h4><article v-for="p in report.items" :key="p.key" class="biz-bar"><div><strong>{{p.name}}</strong><span>¥ {{p.amount}}</span></div><small>{{p.category}} · {{p.receiptCount}}笔关联</small><div class="biz-track"><i :style="{width:width(p.amount)+'%'}"/></div></article></div><div><h4>付款方式</h4><article v-for="p in report.methods" :key="p.method" class="biz-bar"><div><strong>{{p.label}}</strong><span>¥ {{p.amount}}</span></div><div class="biz-track"><i :style="{width:width(p.amount)+'%'}"/></div></article></div></div><p class="b-help">左右两组分别解释相同实收，不能相加作为总收入。采用收款引用的原账单和原成交价，不用当前目录价格回算。</p></section>
<section class="b-card biz-block"><h3>口径与待核实项</h3><p>{{report.rules}}</p><ul v-if="report.warnings.length"><li v-for="(w,k) in report.warnings" :key="k">{{w.note}}<small v-if="w.sourceId"> · {{short(w.sourceId)}}</small></li></ul><p v-else>本次已登记来源未发现上述关联缺项；来源完整性仍需业务人员核实。</p><p class="b-help">这是经营查询原版，重新查询会保存新原版；不是已复核的季度结果。</p></section></section>
<section v-else-if="!loading" class="b-card biz-empty"><BarChart3 :size="36"/><h3>选择范围，开始一次核对</h3><p>查询失败时不会显示一组虚构的零值。</p></section>
<section class="b-card biz-block"><h3><History :size="20"/>我的查询原版</h3><p v-if="!history.length">尚无当前权限可供阅的查询。</p><article v-for="h in history" :key="h.id" class="biz-history"><div><strong>{{names[h.dimension]}}</strong><p>{{time(h.periodFrom)}} — {{time(h.periodTo)}}（右端不含）</p><small>{{short(h.id)}} · {{status[h.status]}}</small></div><button class="b-button outline small" :disabled="busy||loading" @click="read(h.id)">查看原版</button></article><button v-if="next" class="b-button outline" :disabled="busy||loading" @click="loadHistory(true).catch(e=>error=explain(e))">继续加载查询</button></section></div></template>
<style scoped>.business-workspace{display:grid;grid-template-columns:minmax(0,1fr);min-width:0;gap:24px}.biz-filter,.biz-block,.biz-empty{padding:28px}.biz-heading,.biz-result-head,.biz-history{display:flex;justify-content:space-between;align-items:center;gap:20px}.biz-heading h2{margin:8px 0;font-size:25px}.biz-heading p,.biz-result-head p{color:#72837a;line-height:1.7}.biz-fields{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px;margin-top:24px}.biz-filter label{display:grid;gap:9px;font-size:14px;color:#53665c}.biz-filter input:not([type=checkbox]),.biz-filter select{padding:12px;border:1px solid #dce5dc;border-radius:8px;background:white;min-width:0;font:inherit}.biz-filter fieldset{border:0;padding:18px 0;display:flex;flex-wrap:wrap;gap:18px}.biz-filter .b-checkbox{display:flex;align-items:center}.biz-actions{display:flex;gap:18px;align-items:center;margin-top:20px}.biz-actions span{font-size:13px;line-height:1.7;color:#72837a}.biz-results{display:grid;grid-template-columns:minmax(0,1fr);min-width:0;gap:22px}.biz-result-head h2{margin:0}.biz-result-head small{color:#72837a}.biz-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.biz-metrics article{padding:22px;min-width:0}.biz-metrics small{color:#6c8174;font-size:13px}.biz-metrics strong{display:block;font-size:25px;color:#216857;margin:12px 0;overflow-wrap:anywhere}.biz-metrics strong span{font-size:19px;color:#799085}.biz-metrics p{font-size:12px;line-height:1.8;color:#7b8b81}.biz-block h3{display:flex;align-items:center;gap:10px;margin-top:0}.biz-block p{font-size:14px;line-height:1.9}.biz-table{overflow-x:auto;max-width:100%;min-width:0}.biz-table table{border-collapse:collapse;width:100%;min-width:680px;text-align:left;font-size:14px}.biz-table th{background:#f3f7f3;font-weight:500;color:#72837a}.biz-table th,.biz-table td{padding:17px 12px;border-bottom:1px solid #eaf0ea}.biz-table small{display:block;color:#84938a;font-size:12px;line-height:1.7;margin-top:5px}.biz-composition{display:grid;grid-template-columns:1fr 1fr;gap:40px}.biz-bar{margin:22px 0}.biz-bar>div:first-child{display:flex;justify-content:space-between;gap:16px;font-size:14px}.biz-bar small{display:block;color:#7a8e81;font-size:12px;margin:8px 0}.biz-track{height:7px;background:#eef3eb;border-radius:8px;margin-top:12px;overflow:hidden}.biz-track i{height:100%;display:block;background:#3b806b;border-radius:8px}.biz-history{padding:18px 0;border-top:1px solid #edf1eb}.biz-history p{margin:7px 0}.biz-history small{color:#7b8e82}.biz-empty{text-align:center;color:#7b8e82}.biz-block li{font-size:14px;line-height:1.9}.biz-block li small{color:#86958b}@media(max-width:1050px){.biz-metrics{grid-template-columns:1fr 1fr}}@media(max-width:760px){.biz-filter,.biz-block,.biz-empty{padding:20px}.biz-fields{grid-template-columns:1fr}.biz-heading,.biz-result-head,.biz-actions,.biz-history{align-items:flex-start;flex-wrap:wrap}.biz-metrics{gap:12px}.biz-metrics article{padding:16px}.biz-metrics strong{font-size:21px}.biz-composition{grid-template-columns:1fr;gap:10px}.biz-heading h2{font-size:22px}}</style>
